def parser(log: str) -> dict[str, str]:
    import re
    from xml.etree import ElementTree as ET

    def _strip_ns(tag: str) -> str:
        return tag.split("}", 1)[-1] if "}" in tag else tag

    def _norm_name(s: str) -> str:
        # Keep names stable: trim, collapse whitespace; also remove stray newlines inside tokens.
        return re.sub(r"\s+", " ", (s or "")).strip()

    def _mk_testname(classname: str, name: str, suite: str | None = None) -> str:
        classname = _norm_name(classname)
        name = _norm_name(name)
        suite = _norm_name(suite or "")
        if classname and name:
            return f"{classname}.{name}"
        if suite and name:
            return f"{suite}.{name}"
        return classname or name or suite

    def _status_from_xml_children(tc_elem) -> str:
        # Priority: fail > skip > pass
        status_attr = (tc_elem.attrib.get("status") or "").lower()
        result_attr = (tc_elem.attrib.get("result") or "").lower()
        name_attr = tc_elem.attrib.get("name") or ""
        classname_attr = tc_elem.attrib.get("classname") or ""
        full = f"{classname_attr}.{name_attr}"

        if (
            status_attr in {"notrun", "disabled"}
            or result_attr in {"suppressed", "skipped", "disabled"}
            or name_attr.startswith("DISABLED_")
            or ".DISABLED_" in full
        ):
            # still allow fail marker to override below if present
            base = "skip"
        else:
            base = "pass"

        has_fail = False
        has_skip = False
        for child in list(tc_elem):
            t = _strip_ns(child.tag).lower()
            if t in {"failure", "error"}:
                has_fail = True
            elif t in {"skipped", "skip"}:
                has_skip = True

        if has_fail:
            return "fail"
        if has_skip:
            return "skip"
        return base

    # ---------- 1) Try to locate and parse XML (best effort) ----------
    text = log.replace("\r\n", "\n").replace("\r", "\n")

    # Try to crop to an XML-ish region to avoid leading noise.
    start = text.find("<testsuites")
    if start == -1:
        start = text.find("<?xml")
    xml_region = text[start:] if start != -1 else text

    # If we can find a proper closing tag, crop; otherwise keep partial (ET may fail).
    end = xml_region.rfind("</testsuites>")
    if end != -1:
        xml_region_cropped = xml_region[: end + len("</testsuites>")]
    else:
        xml_region_cropped = xml_region

    results: dict[str, str] = {}

    def _emit(name: str, status: str):
        if not name:
            return
        # Keep latest seen (usually identical); fail should win over pass/skip if duplicates happen.
        prev = results.get(name)
        if prev == "fail":
            return
        if status == "fail":
            results[name] = "fail"
        elif prev is None:
            results[name] = status
        elif prev == "pass" and status == "skip":
            # don't downgrade pass to skip
            return
        else:
            results[name] = prev

    # Basic sanitization to make ET more likely to work on wrapped logs:
    # - remove control chars (except \n, \t)
    # - do NOT collapse whitespace globally (would corrupt content); ET can handle newlines in attrs if well-formed.
    xml_sanitized = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", xml_region_cropped)

    parsed_xml = False
    try:
        root = ET.fromstring(xml_sanitized)
        parsed_xml = True
    except Exception:
        parsed_xml = False

    if parsed_xml:
        # Root may be <testsuites> or <testsuite>
        for suite in root.iter():
            if _strip_ns(suite.tag).lower() != "testsuite":
                continue
            suite_name = suite.attrib.get("name") or ""
            for tc in suite:
                if _strip_ns(tc.tag).lower() != "testcase":
                    continue
                tname = _mk_testname(tc.attrib.get("classname", ""), tc.attrib.get("name", ""), suite_name)
                _emit(tname, _status_from_xml_children(tc))

        if results:
            return results  # best path

    # ---------- 2) Fallback: regex-based XML-ish extraction (handles truncated/broken XML) ----------
    # We avoid trying to "fix" broken quotes globally; instead extract attrs with tolerant regex.
    region = xml_region  # even if no closing tag exists

    # Iterate testsuites to keep suite context as fallback classname.
    # We'll scan sequentially to associate each testcase with the most recent testsuite name.
    suite_name = ""
    i = 0
    suite_pat = re.compile(r"<\s*testsuite\b([^>]*)>", re.IGNORECASE | re.DOTALL)
    tc_pat = re.compile(r"<\s*testcase\b([^>]*?)(/?>)", re.IGNORECASE | re.DOTALL)

    def get_attr_loose(attr_blob: str, key: str) -> str | None:
        # Supports name="..." or name='...'; tolerant to newlines; stops at matching quote.
        m = re.search(rf"""\b{re.escape(key)}\s*=\s*(["'])(.*?)\1""", attr_blob, re.IGNORECASE | re.DOTALL)
        if m:
            return m.group(2)
        return None

    # Precompute all tag hits (suite open and testcase open) with positions.
    hits = []
    for m in suite_pat.finditer(region):
        hits.append(("suite", m.start(), m.end(), m.group(1)))
    for m in tc_pat.finditer(region):
        hits.append(("tc", m.start(), m.end(), m.group(1)))
    hits.sort(key=lambda x: x[1])

    # To detect inner markers for a testcase, look from its end to the next testcase start or testsuite end.
    # This works even if testcase isn't properly closed.
    next_tag_pat = re.compile(r"<\s*(testcase|testsuite|/testsuite|/testsuites)\b", re.IGNORECASE)

    for idx, (kind, start_pos, end_pos, blob) in enumerate(hits):
        if kind == "suite":
            suite_name = _norm_name(get_attr_loose(blob, "name") or suite_name)
            continue

        attrs = blob
        name = _norm_name(get_attr_loose(attrs, "name") or "")
        classname = _norm_name(get_attr_loose(attrs, "classname") or "")

        # Determine slice for inner content markers
        inner_start = end_pos
        inner_end = len(region)
        nm = next_tag_pat.search(region, inner_start)
        if nm:
            inner_end = nm.start()
        inner = region[inner_start:inner_end]

        status_attr = _norm_name((get_attr_loose(attrs, "status") or "")).lower()
        result_attr = _norm_name((get_attr_loose(attrs, "result") or "")).lower()

        full = f"{classname}.{name}"
        status = "pass"
        if (
            status_attr in {"notrun", "disabled"}
            or result_attr in {"suppressed", "skipped", "disabled"}
            or name.startswith("DISABLED_")
            or ".DISABLED_" in full
        ):
            status = "skip"

        if re.search(r"<\s*(failure|error)\b", inner, re.IGNORECASE):
            status = "fail"
        elif re.search(r"<\s*skipped\b", inner, re.IGNORECASE):
            status = "skip"

        tname = _mk_testname(classname, name, suite_name)
        _emit(tname, status)

    # ---------- 3) Non-XML fallbacks (pytest / unittest / go test / jest-like) ----------
    # Pytest: file.py::test_name PASSED/FAILED/SKIPPED/ERROR
    for m in re.finditer(r"(?m)^\s*(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\s*$", text):
        tname = m.group(1).strip()
        st = m.group(2)
        _emit(tname, "pass" if st == "PASSED" else "skip" if st == "SKIPPED" else "fail")

    # Go test: --- PASS: TestName / FAIL / SKIP
    for m in re.finditer(r"(?m)^\s*---\s+(PASS|FAIL|SKIP):\s+(\S+)", text):
        st, tname = m.group(1), m.group(2)
        _emit(tname, "pass" if st == "PASS" else "skip" if st == "SKIP" else "fail")

    # unittest: test_method (TestClass) ... ok/FAIL/ERROR/skipped
    for m in re.finditer(r"(?m)^\s*(\w+)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\s*$", text):
        method, cls, st = m.group(1), m.group(2), m.group(3)
        tname = f"{cls}.{method}"
        _emit(tname, "pass" if st == "ok" else "skip" if st == "skipped" else "fail")

    return results

