def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}

    def set_status(name: str, status: str):
        if not name:
            return
        n = name.strip()
        # normalize suite/name separator and spaces
        n = re.sub(r"\s*::\s*", "::", n)
        n = re.sub(r"[ \t]+", " ", n)
        severity = {"fail": 2, "pass": 1, "skip": 0}
        old = results.get(n)
        if old is None or severity.get(status, -1) > severity.get(old, -1):
            results[n] = status

    # Helper to join with duplicate-boundary suppression
    def join_suppress(prev: str, nxt: str) -> str:
        if not prev:
            return nxt
        if not nxt:
            return prev
        if prev[-1] == nxt[0]:
            nxt = nxt[1:]
        return prev + nxt

    # 1) Parse any JUnit XML if present
    open_close_re = re.compile(r"<testcase\b([^>]*)>(.*?)</testcase>", re.DOTALL | re.IGNORECASE)
    attrs_re = re.compile(r'(\w+)\s*=\s*"([^"]*)"', re.IGNORECASE)
    for m in open_close_re.finditer(log):
        attrs = m.group(1) or ""
        body = m.group(2) or ""
        classname = None
        name = None
        for k, v in attrs_re.findall(attrs):
            kl = k.lower()
            if kl == "classname":
                classname = v.strip()
            elif kl == "name":
                name = v.strip()
        testname = None
        if classname and name:
            testname = f"{classname}::{name}"
        elif name:
            testname = name
        elif classname:
            testname = classname
        if testname:
            bl = body.lower()
            if "<skipped" in bl:
                set_status(testname, "skip")
            elif "<failure" in bl or "<error" in bl:
                set_status(testname, "fail")
            else:
                set_status(testname, "pass")

    self_closing_re = re.compile(r"<testcase\b([^>]*)\s*/>", re.IGNORECASE)
    for m in self_closing_re.finditer(log):
        attrs = m.group(1) or ""
        classname = None
        name = None
        for k, v in attrs_re.findall(attrs):
            kl = k.lower()
            if kl == "classname":
                classname = v.strip()
            elif kl == "name":
                name = v.strip()
        testname = None
        if classname and name:
            testname = f"{classname}::{name}"
        elif name:
            testname = name
        elif classname:
            testname = classname
        if testname:
            set_status(testname, "pass")

    # 2) Parse failure block headers for full names, reconstruct with suppression across newlines
    # Pattern: **** TEST 'suite :: name:cfg' FAILED ****
    fail_block_re = re.compile(r"\*+\s*TEST\s+'(.+?)'\s+FAILED\s*\*+", re.DOTALL | re.IGNORECASE)
    for m in fail_block_re.finditer(log):
        raw = m.group(1)
        # Reconstruct across newlines while suppressing duplicated boundary chars
        parts = raw.replace("\r", "").split("\n")
        if parts:
            name_joined = parts[0]
            for part in parts[1:]:
                name_joined = join_suppress(name_joined, part)
            set_status(name_joined, "fail")

    # 3) Parse LIT lines with robust reconstruction
    status_prefix_re = re.compile(r"^\s*(PASS|FAIL|XFAIL|XPASS|UNSUPPORTED|SKIPPED):", re.IGNORECASE)
    # Accept duplicated letters in 'of' due to wrapping/duplication
    trailer_re = re.compile(r"\(\s*\d+\s+o+f+\s+\d+\s*\)\s*$", re.IGNORECASE)
    # Lines that indicate we should stop accumulating this logical line
    header_break_re = re.compile(
        r"^\*{5,}|^Exit Code:|^Standard Error:|^Build setup steps:|^Build steps:|^Command:|^--\s*$|^In file included|^-- Testing:|^Testing Time:",
        re.IGNORECASE,
    )

    lines = log.splitlines()
    logical_lines: list[str] = []
    buf = None

    def flush_buf():
        nonlocal buf
        if buf is not None:
            # Ensure no stray CRs and collapse any remaining newlines (shouldn't be any)
            s = buf.replace("\r", "").replace("\n", "")
            logical_lines.append(s)
            buf = None

    i = 0
    while i < len(lines):
        line = lines[i]
        if status_prefix_re.match(line):
            flush_buf()
            buf = line
            j = i + 1
            while j < len(lines):
                nxt = lines[j]
                if status_prefix_re.match(nxt) or header_break_re.match(nxt):
                    break
                buf = join_suppress(buf, nxt)
                if trailer_re.search(nxt) or trailer_re.search(buf):
                    j += 1
                    break
                j += 1
            i = j
            flush_buf()
            continue
        else:
            i += 1

    lit_re = re.compile(
        r"^\s*(PASS|FAIL|XFAIL|XPASS|UNSUPPORTED|SKIPPED):\s+(.+?)\s+::\s+(.+?)(?:\s+\(\d+\s+o+f+\s+\d+\)\s*)?$",
        re.IGNORECASE,
    )

    def map_status(s: str) -> str:
        s = s.upper()
        if s == "PASS":
            return "pass"
        if s in ("FAIL", "XPASS"):
            return "fail"
        if s == "XFAIL":
            return "pass"
        if s in ("UNSUPPORTED", "SKIPPED"):
            return "skip"
        return "fail"

    for ll in logical_lines:
        m = lit_re.match(ll)
        if not m:
            continue
        status_raw, suite, name = m.groups()
        testname = f"{suite}::{name}"
        set_status(testname, map_status(status_raw))

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    priority = {"pass": 1, "skip": 2, "fail": 3}

    def normalize_pkg(pkg: str | None) -> str:
        if not pkg:
            return ""
        pkg = re.sub(r"\s+", "", pkg)
        pkg = re.sub(r"^github\.[^/]+/", "github.com/", pkg)
        pkg = re.sub(r"^github\.[^/]+$", "github.com", pkg)
        return pkg

    def normalize_test(test: str | None) -> str:
        if not test:
            return ""
        test = re.sub(r"\s+", "", test)
        test = re.sub(r"/+", "/", test)
        return test

    def make_name(pkg: str | None, test: str | None) -> str:
        pkg = normalize_pkg(pkg)
        test = normalize_test(test)
        if pkg and test:
            return f"{pkg}.{test}"
        return test or pkg

    def update(name: str, status: str):
        if not name:
            return
        status = status.lower()
        if status == "error":
            status = "fail"
        if status not in priority:
            return
        prev = results.get(name)
        if prev is None or priority[status] >= priority[prev]:
            results[name] = status

    def parse_output_text(text: str, pkg: str | None = None):
        if not text:
            return
        text = text.replace("\\n", "\n")
        for match in re.finditer(r"---\s+(PASS|FAIL|SKIP|ERROR):\s+(.+?)(?:\s+\(|\n|$)", text, re.IGNORECASE):
            status = match.group(1).lower()
            test_name = match.group(2).strip()
            update(make_name(pkg, test_name), status)

    def extract_objects(text: str) -> list[str]:
        objs: list[str] = []
        depth = 0
        in_str = False
        esc = False
        start = None
        for i, ch in enumerate(text):
            if ch == '"' and not esc:
                in_str = not in_str
            if ch == "\\" and in_str:
                esc = not esc
            else:
                esc = False
            if not in_str:
                if ch == "{":
                    if depth == 0:
                        start = i
                    depth += 1
                elif ch == "}" and depth > 0:
                    depth -= 1
                    if depth == 0 and start is not None:
                        objs.append(text[start : i + 1])
                        start = None
        return objs

    for obj in extract_objects(log):
        event = None
        try:
            event = json.loads(obj)
        except Exception:
            pass

        if event is not None:
            action = event.get("Action")
            test = event.get("Test")
            pkg = event.get("Package")
            if action in ("pass", "fail", "skip", "error") and test:
                update(make_name(pkg, test), action)
            output = event.get("Output")
            if output:
                parse_output_text(output, pkg)
            continue

        action_match = re.search(r'"Action"\s*:\s*"([^"]+)"', obj, re.S)
        test_match = re.search(r'"Test"\s*:\s*"([^"]+)"', obj, re.S)
        pkg_match = re.search(r'"Package"\s*:\s*"([^"]+)"', obj, re.S)
        output_match = re.search(r'"Output"\s*:\s*"([^"]*)"', obj, re.S)
        action = action_match.group(1) if action_match else None
        test = test_match.group(1) if test_match else None
        pkg = pkg_match.group(1) if pkg_match else None
        if action in ("pass", "fail", "skip", "error") and test:
            update(make_name(pkg, test), action)
        if output_match:
            parse_output_text(output_match.group(1), pkg)

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    def extract_json_objects(text: str):
        objs = []
        n = len(text)
        i = 0
        while True:
            start = text.find("{", i)
            if start < 0:
                break
            depth = 0
            in_str = False
            esc = False
            j = start
            while j < n:
                ch = text[j]
                if in_str:
                    if esc:
                        esc = False
                    elif ch == "\\":
                        esc = True
                    elif ch == '"':
                        in_str = False
                else:
                    if ch == '"':
                        in_str = True
                    elif ch == "{":
                        depth += 1
                    elif ch == "}":
                        depth -= 1
                        if depth == 0:
                            objs.append(text[start : j + 1])
                            i = j + 1
                            break
                j += 1
            else:
                break
        return objs

    def compact_ws(s: str) -> str:
        # In this dataset, console wrapping injects whitespace/newlines into JSON text.
        # Remove all whitespace characters occurring within field strings.
        return re.sub(r"\s+", "", s or "")

    results: dict[str, str] = {}

    # Parse all json events; take any event containing Action and Test and Package.
    for obj in extract_json_objects(log):
        try:
            ev = json.loads(obj)
        except Exception:
            continue

        action = (ev.get("Action") or "").lower()
        if action not in ("pass", "fail", "skip"):
            continue

        pkg = compact_ws(ev.get("Package", ""))
        test = compact_ws(ev.get("Test", ""))

        if pkg and test:
            results[f"{pkg}/{test}"] = action

    # If we got nothing, fall back to a tolerant regex over raw text (like the draft),
    # but still normalize whitespace within captured values.
    if not results:
        action_re = re.compile(r'"Action"\s*:\s*"(?P<action>pass|fail|skip)"', re.IGNORECASE)
        pkg_re = re.compile(r'"Package"\s*:\s*"(?P<pkg>[^"]+)"', re.DOTALL)
        test_re = re.compile(r'"Test"\s*:\s*"(?P<test>[^"]+)"', re.DOTALL)

        for m in re.finditer(r"\{.*?\}", log, re.DOTALL):
            obj = m.group(0)
            ma = action_re.search(obj)
            mp = pkg_re.search(obj)
            mt = test_re.search(obj)
            if not (ma and mp and mt):
                continue
            action = ma.group("action").lower()
            pkg = compact_ws(mp.group("pkg"))
            test = compact_ws(mt.group("test"))
            if pkg and test:
                results[f"{pkg}/{test}"] = action

    # Final defensive normalization
    for k, v in list(results.items()):
        if v not in ("pass", "fail", "skip"):
            results[k] = "fail"

    return results

