log_parser:
def parser(log: str) -> dict[str, str]:
    import json
    import re

    # precedence: fail > skip > pass
    rank = {"pass": 0, "skip": 1, "fail": 2}

    def upd(results, name, status):
        if not name or status not in rank:
            return
        cur = results.get(name)
        if cur is None or rank[status] > rank[cur]:
            results[name] = status

    def canonical_pkg(pkg: str) -> str:
        if not isinstance(pkg, str):
            return pkg
        p = pkg.strip()
        if p.startswith("github") and "/hashicorp/" in p:
            p = re.sub(r"^github\.\.com\b", "github.com", p)
            p = re.sub(r"^github\.ccom\b", "github.com", p)
            p = re.sub(r"^github\.comm\b", "github.com", p)
            p = re.sub(r"^github\.coom\b", "github.com", p)
            p = re.sub(r"^github\.c+o+m\b", "github.com", p)
        return p

    def canonical_test(t: str) -> str:
        if not isinstance(t, str):
            return t
        return t.strip()

    def iter_go_test_json_events(ps_text: str):
        """
        Reconstruct JSON events from PowerShell-wrapped Get-Content output.
        Strategy: each event starts on a line whose first non-space is '{'.
        Subsequent wrapped lines are appended verbatim (no .strip()).
        """
        buf = None
        for raw_ln in ps_text.splitlines():
            ln = raw_ln.rstrip("\r")

            # skip PowerShell prompts/noise
            if re.match(r"^\s*PS>.*$", ln):
                continue
            if re.match(r"^\s*ContainerAdministrator@.*$", ln):
                continue
            if ln == "":
                continue

            lstripped = ln.lstrip()
            if lstripped.startswith("{"):
                # flush previous
                if buf is not None:
                    yield buf
                # keep from the first '{' to preserve exact JSON characters
                buf = ln[ln.find("{") :]
            else:
                if buf is not None:
                    # append verbatim continuation
                    buf += ln
        if buf is not None:
            yield buf

    results: dict[str, str] = {}
    saw_action_events = False

    for s in iter_go_test_json_events(log):
        try:
            ev = json.loads(s)
        except Exception:
            continue

        pkg = canonical_pkg(ev.get("Package"))
        test = canonical_test(ev.get("Test"))
        action = ev.get("Action")

        if action in ("pass", "fail", "skip") and pkg and test:
            saw_action_events = True
            upd(results, f"{pkg}/{test}", "fail" if action == "fail" else action)

        # Only use Output fallback if we didn't see Action events at all
        # (avoids double-counting/weird variants when Output is wrapped).
        if not saw_action_events:
            out = ev.get("Output")
            if isinstance(out, str) and pkg:
                m = re.search(r"---\s+(PASS|FAIL|SKIP):\s+([^\s(]+)", out)
                if m:
                    status = m.group(1).lower()
                    tname = canonical_test(m.group(2))
                    upd(results, f"{pkg}/{tname}", "fail" if status == "fail" else status)

    # Plain-text fallback if no JSON-derived results
    if not results:
        current_pkg = None
        for raw_ln in log.splitlines():
            ln = raw_ln.rstrip("\r")
            if re.match(r"^\s*PS>.*$", ln) or re.match(r"^\s*ContainerAdministrator@.*$", ln):
                continue
            m = re.match(r"^\s*ok\s+(\S+)\s", ln)
            if m:
                current_pkg = canonical_pkg(m.group(1))
                continue
            m = re.match(r"---\s+(PASS|FAIL|SKIP):\s+([^\s(]+)", ln)
            if m and current_pkg:
                status = m.group(1).lower()
                tname = canonical_test(m.group(2))
                upd(results, f"{current_pkg}/{tname}", "fail" if status == "fail" else status)

    return results

