log_parser:
def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def status_precedence(s: str) -> int:
        return {"skip": 0, "pass": 1, "fail": 2}.get(s, -1)

    def set_result(name: str, status: str) -> None:
        if not name:
            return
        if status not in ("pass", "fail", "skip"):
            status = "fail"
        prev = results.get(name)
        if prev is None or status_precedence(status) >= status_precedence(prev):
            results[name] = status

    def extract_json_objects(text: str) -> list[str]:
        objs: list[str] = []
        i, n = 0, len(text)
        while i < n:
            if text[i] != "{":
                i += 1
                continue
            start = i
            depth = 0
            in_str = False
            esc = False
            while i < n:
                ch = text[i]
                if in_str:
                    if esc:
                        esc = False
                    elif ch == "\\":
                        esc = True
                    elif ch == '"':
                        in_str = False
                else:
                    if ch == '"':
                        in_str = True
                    elif ch == "{":
                        depth += 1
                    elif ch == "}":
                        depth -= 1
                        if depth == 0:
                            i += 1
                            objs.append(text[start:i])
                            break
                i += 1
            else:
                break
        return objs

    # Primary: parse Go 'go test -json' output, robust to terminal hard-wraps
    for blob in extract_json_objects(log):
        repaired = re.sub(r"[\r\n]+", "", blob).strip()
        try:
            evt = json.loads(repaired)
        except Exception:
            continue

        action = evt.get("Action")
        if action not in ("pass", "fail", "skip"):
            continue

        pkg = (evt.get("Package") or "").strip()
        test = evt.get("Test")
        test = test.strip() if isinstance(test, str) else ""
        name = f"{pkg}/{test}" if test else pkg
        set_result(name, "fail" if action == "fail" else action)

    # Fallback: plain text go test output
    if not results:
        for m in re.finditer(r"---\s+(PASS|FAIL|SKIP):\s+([^\s(]+)", log):
            st = m.group(1).lower()
            tc = m.group(2).strip()
            set_result(tc, "fail" if st == "fail" else ("skip" if st == "skip" else "pass"))

    return results

