def parser(log: str) -> dict[str, str]:
    import re

    def norm_status(s: str) -> str:
        s = s.lower()
        if s in ("passed", "pass", "ok", "✓"):
            return "pass"
        if s in ("failed", "fail", "error", "✕", "xfail", "xfailed", "xpass"):
            return "fail"
        if s in ("skipped", "skip", "xskip", "○"):
            return "skip"
        return "fail"

    def clean_nodeid(s: str) -> str:
        s = s.replace("\r", "").replace("\n", "")
        s = s.replace("\\", "/")
        s = re.sub(r":{3,}", "::", s)
        s = re.sub(r"\s+", "", s)
        # Trim leading noise to common prefixes
        prefixes = ("sdk/", "tests/", "src/")
        for p in prefixes:
            idx = s.find(p)
            if idx != -1:
                s = s[idx:]
                break
        return s

    def is_probable_test(nodeid: str) -> bool:
        # Must look like a pytest test path with "::" and sensible prefix
        if "::" not in nodeid:
            return False
        if not (nodeid.startswith("sdk/") or nodeid.startswith("tests/") or nodeid.startswith("src/")):
            return False
        # Last part should be non-empty
        last = nodeid.split("::")[-1]
        return bool(last)

    def severity(status: str) -> int:
        if status == "pass":
            return 0
        if status == "skip":
            return 1
        return 2  # fail

    # Brace-balanced slice around a given position
    def slice_object_around(pos: int) -> str | None:
        # Find nearest preceding '{'
        start = log.rfind("{", 0, pos)
        if start == -1:
            return None
        depth = 0
        in_str = False
        escape = False
        for i in range(start, len(log)):
            ch = log[i]
            if in_str:
                if escape:
                    escape = False
                elif ch == "\\":
                    escape = True
                elif ch == '"':
                    in_str = False
            else:
                if ch == '"':
                    in_str = True
                elif ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        return log[start : i + 1]
        # Fallback: return a capped slice if unmatched
        return log[start : min(len(log), start + 12000)]

    results: dict[str, str] = {}

    # Patterns for outcomes/status within an object
    outcome_kv_re = re.compile(
        r'"(?:outcome|status)"\s*:\s*"(passed|failed|skipped|error|xfail|xpass)"',
        re.IGNORECASE,
    )
    phase_outcome_res = [
        re.compile(
            r'"call"\s*:\s*\{[^{}]*"(?:outcome|status)"\s*:\s*"(passed|failed|skipped|error|xfail|xpass)"',
            re.IGNORECASE | re.DOTALL,
        ),
        re.compile(
            r'"setup"\s*:\s*\{[^{}]*"(?:outcome|status)"\s*:\s*"(passed|failed|skipped|error|xfail|xpass)"',
            re.IGNORECASE | re.DOTALL,
        ),
        re.compile(
            r'"teardown"\s*:\s*\{[^{}]*"(?:outcome|status)"\s*:\s*"(passed|failed|skipped|error|xfail|xpass)"',
            re.IGNORECASE | re.DOTALL,
        ),
    ]

    # Find all nodeid occurrences
    node_matches = list(re.finditer(r'"nodeid"\s*:\s*"(.*?)"', log, flags=re.IGNORECASE | re.DOTALL))

    # Primary pass: search within brace-balanced object containing the nodeid
    for m in node_matches:
        raw_nodeid = m.group(1)
        nodeid = clean_nodeid(raw_nodeid)
        if not is_probable_test(nodeid):
            continue

        obj_slice = slice_object_around(m.start())
        if not obj_slice:
            continue

        # Prefer phase outcomes; choose most severe if multiple
        best_status = None
        best_sev = -1
        for rx in phase_outcome_res:
            for pm in rx.finditer(obj_slice):
                st = norm_status(pm.group(1))
                sev = severity(st)
                if sev > best_sev:
                    best_status, best_sev = st, sev

        # If no phase outcome found, look for direct outcome/status
        if best_status is None:
            kv = outcome_kv_re.search(obj_slice)
            if kv:
                st = norm_status(kv.group(1))
                best_status = st
                best_sev = severity(st)

        if best_status:
            results[nodeid] = best_status

    # Secondary pass: limited forward window to next nodeid to catch nearby outcomes (avoid collector-level backward association)
    for i, m in enumerate(node_matches):
        raw_nodeid = m.group(1)
        nodeid = clean_nodeid(raw_nodeid)
        if not is_probable_test(nodeid):
            continue
        if nodeid in results:
            continue
        start = m.end()
        next_start = node_matches[i + 1].start() if i + 1 < len(node_matches) else len(log)
        window = log[start : min(next_start, start + 4000)]
        # Prefer phase outcomes
        best_status = None
        best_sev = -1
        for rx in phase_outcome_res:
            pm = rx.search(window)
            if pm:
                st = norm_status(pm.group(1))
                best_status = st
                best_sev = severity(st)
                break
        if best_status is None:
            kv = outcome_kv_re.search(window)
            if kv:
                best_status = norm_status(kv.group(1))
        if best_status:
            results[nodeid] = best_status

    # Fallback: textual pytest lines
    text_re_a = re.compile(
        r'([^\s][^\n\r]*?::[^\s][^\n\r]*)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b',
        re.IGNORECASE,
    )
    for m in text_re_a.finditer(log):
        testid, status = m.groups()
        nodeid = clean_nodeid(testid)
        if is_probable_test(nodeid):
            results[nodeid] = norm_status(status)

    text_re_b = re.compile(
        r'(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\s+([^\s][^\n\r]*?::[^\s][^\n\r]*)\b',
        re.IGNORECASE,
    )
    for m in text_re_b.finditer(log):
        status, testid = m.groups()
        nodeid = clean_nodeid(testid)
        if is_probable_test(nodeid):
            results[nodeid] = norm_status(status)

    text_re_c = re.compile(r'FAILED\s+([^\s][^\n\r]*?::[^\s][^\n\r]*)\b', re.IGNORECASE)
    for m in text_re_c.finditer(log):
        nodeid = clean_nodeid(m.group(1))
        if is_probable_test(nodeid):
            results[nodeid] = "fail"

    # Ensure statuses are only pass/fail/skip
    for k, v in list(results.items()):
        if v not in ("pass", "fail", "skip"):
            results[k] = "fail"

    return results

def parser(log: str) -> dict[str, str]:
    # Robust test output parser for pytest JSON and textual outputs
    # Returns mapping: { "test_case_name": "pass|fail|skip", ... }
    import json
    import re
    from pathlib import Path
    from typing import Any, Dict, List, Optional, Tuple

    def map_status(s: str) -> str:
        if not s:
            return "fail"
        v = s.strip().lower()
        if v in {"passed", "pass", "ok", "xpass", "xpassed"}:
            return "pass"
        if v in {"skipped", "skip", "xfail", "xfailed"}:
            return "skip"
        # treat failed/error/others as fail
        return "fail"

    def is_test_function_nodeid(nodeid: str) -> bool:
        # pytest nodeid format: file.py::[Class::]test_name[params]
        if not nodeid or "::" not in nodeid:
            return False
        last = nodeid.split("::")[-1]
        # allow parametrized (may include brackets), ensure base name starts with lowercase "test"
        base = last.split("[", 1)[0]
        return base.startswith("test")

    def select_better(existing: Tuple[str, int], new_status: str, new_prio: int) -> Tuple[str, int]:
        # Higher priority wins; on tie, keep "worst" outcome (fail > skip > pass)
        if new_prio > existing[1]:
            return (new_status, new_prio)
        if new_prio < existing[1]:
            return existing
        # same priority, apply severity ordering
        order = {"fail": 2, "skip": 1, "pass": 0}
        if order.get(map_status(new_status), 0) > order.get(map_status(existing[0]), 0):
            return (new_status, new_prio)
        return existing

    def add_result(results: Dict[str, str], nodeid: str, status: str) -> None:
        if not nodeid:
            return
        # Keep the worst status if re-encountered
        if nodeid in results:
            order = {"fail": 2, "skip": 1, "pass": 0}
            if order[map_status(status)] > order[results[nodeid]]:
                results[nodeid] = map_status(status)
        else:
            results[nodeid] = map_status(status)

    def normalize_nodeid(nodeid: str) -> str:
        # Remove hard-wrapped CR/LF that can split nodeids across lines
        return nodeid.replace("\r", "").replace("\n", "")

    def collect_from_tests_list(tests: List[Any]) -> Dict[str, str]:
        out: Dict[str, str] = {}
        for t in tests:
            if not isinstance(t, dict):
                continue
            nodeid = t.get("nodeid") or t.get("node")
            outcome = t.get("outcome")
            if nodeid and outcome:
                nid = normalize_nodeid(str(nodeid))
                if is_test_function_nodeid(nid):
                    add_result(out, nid, str(outcome))
        return out

    def collect_from_reports_list(reports: List[Any]) -> Dict[str, str]:
        # Handle pytest-reportlog style: multiple phase reports per nodeid
        # Prefer when == "call", else any available; combine to worst result
        per_node: Dict[str, Tuple[str, int]] = {}  # nodeid -> (status, priority)
        for r in reports:
            if not isinstance(r, dict):
                continue
            nodeid = r.get("nodeid") or r.get("node")
            outcome = r.get("outcome")
            if not nodeid or not outcome:
                continue
            nid = normalize_nodeid(str(nodeid))
            if not is_test_function_nodeid(nid):
                continue
            when = r.get("when")
            prio = 1
            if isinstance(when, str):
                when_l = when.lower()
                if when_l == "call":
                    prio = 3
                elif when_l == "teardown":
                    prio = 2
                else:
                    prio = 1
            status = map_status(str(outcome))
            if nid in per_node:
                per_node[nid] = select_better(per_node[nid], status, prio)
            else:
                per_node[nid] = (status, prio)
        out: Dict[str, str] = {}
        for k, (status, _prio) in per_node.items():
            out[k] = map_status(status)
        return out

    def collect_from_json_obj(data: Any) -> Dict[str, str]:
        # Try standard keys first
        results: Dict[str, str] = {}
        if isinstance(data, dict):
            # pytest-json-report plugin
            if isinstance(data.get("tests"), list):
                res = collect_from_tests_list(data["tests"])
                if res:
                    results.update(res)
            # pytest-reportlog plugin
            if isinstance(data.get("reports"), list):
                res = collect_from_reports_list(data["reports"])
                if res:
                    results.update(res)
            # Some tools may place results under other keys, try to find lists of dicts with nodeid+outcome
            if not results:
                for val in data.values():
                    if isinstance(val, list):
                        # try as tests
                        res1 = collect_from_tests_list(val)
                        res2 = collect_from_reports_list(val)
                        if res1:
                            results.update(res1)
                        if res2:
                            results.update(res2)
                # As last resort, deep scan dicts to pick any object with nodeid+outcome
                def deep_scan(obj: Any) -> None:
                    if isinstance(obj, dict):
                        nodeid = obj.get("nodeid") or obj.get("node")
                        outcome = obj.get("outcome")
                        when = obj.get("when")
                        if nodeid and outcome:
                            nid = normalize_nodeid(str(nodeid))
                            if is_test_function_nodeid(nid):
                                prio = 1
                                if isinstance(when, str):
                                    wl = when.lower()
                                    prio = 3 if wl == "call" else (2 if wl == "teardown" else 1)
                                status = map_status(str(outcome))
                                if nid in temp:
                                    temp[nid] = select_better(temp[nid], status, prio)
                                else:
                                    temp[nid] = (status, prio)
                        for v in obj.values():
                            deep_scan(v)
                    elif isinstance(obj, list):
                        for it in obj:
                            deep_scan(it)
                temp: Dict[str, Tuple[str, int]] = {}
                deep_scan(data)
                if temp:
                    for k, (status, _p) in temp.items():
                        results[k] = map_status(status)
        elif isinstance(data, list):
            # Maybe top-level list of test reports
            res = collect_from_tests_list(data)
            if not res:
                res = collect_from_reports_list(data)
            results.update(res)
        return results

    def try_load_json_from_file() -> Optional[Dict[str, str]]:
        p = Path("reports") / "pytest-results.json"
        if not p.exists():
            return None
        try:
            with p.open("r", encoding="utf-8") as f:
                data = json.load(f)
            res = collect_from_json_obj(data)
            return res if res else {}
        except Exception:
            return None

    def try_load_json_from_log_text(log_text: str) -> Optional[Dict[str, str]]:
        try:
            data = json.loads(log_text)
            res = collect_from_json_obj(data)
            return res if res else {}
        except Exception:
            return None

    def object_aware_scan(log_text: str) -> Dict[str, str]:
        # Scan for JSON object substrings and match nodeid+outcome within the same object
        results: Dict[str, Tuple[str, int]] = {}
        stack: List[int] = []
        for i, ch in enumerate(log_text):
            if ch == "{":
                stack.append(i)
            elif ch == "}" and stack:
                start = stack.pop()
                obj_text = log_text[start : i + 1]
                # Quick filter to avoid expensive regex on irrelevant chunks
                if '"nodeid"' not in obj_text and '"node"' not in obj_text:
                    continue
                # Extract fields within this object
                m_node = re.search(r'"(?:nodeid|node)"\s*:\s*"((?:[^"\\]|\\.)*)"', obj_text)
                m_out = re.search(r'"outcome"\s*:\s*"((?:[^"\\]|\\.)*)"', obj_text)
                m_when = re.search(r'"when"\s*:\s*"((?:[^"\\]|\\.)*)"', obj_text)
                if not m_node or not m_out:
                    continue
                nodeid_raw = m_node.group(1)
                outcome_raw = m_out.group(1)
                when_raw = m_when.group(1) if m_when else None
                # Unescape common sequences in JSON strings
                try:
                    nodeid = bytes(nodeid_raw, "utf-8").decode("unicode_escape")
                except Exception:
                    nodeid = nodeid_raw
                nodeid = normalize_nodeid(nodeid)
                outcome = outcome_raw
                when = when_raw
                if not is_test_function_nodeid(nodeid):
                    continue
                prio = 1
                if isinstance(when, str):
                    wl = when.lower()
                    prio = 3 if wl == "call" else (2 if wl == "teardown" else 1)
                status = map_status(outcome)
                if nodeid in results:
                    results[nodeid] = select_better(results[nodeid], status, prio)
                else:
                    results[nodeid] = (status, prio)
        flat: Dict[str, str] = {}
        for k, (status, _p) in results.items():
            flat[k] = map_status(status)
        return flat

    def parse_textual(log_text: str) -> Dict[str, str]:
        results: Dict[str, str] = {}

        def add(id_: str, st: str):
            id_clean = normalize_nodeid(id_.strip())
            # Ensure it's a function-level pytest id
            if not id_clean:
                return
            # Some textual reports might include class-only entries; filter them
            if is_test_function_nodeid(id_clean):
                add_result(results, id_clean, st)

        # Pytest console pattern: file::[Class::]test STATUS
        # Allow optional progress bracket like [ 50%]
        pytest_re = re.compile(r'(?m)^(?P<id>.+?::.+?)\s+(?:\[\s*\d+%?\]\s*)?(?P<st>PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b')
        for m in pytest_re.finditer(log_text):
            add(m.group("id"), m.group("st"))

        # unittest pattern: TestClass.test_method ... ok/FAIL/ERROR/skipped
        ut_re = re.compile(r'(?m)^(?P<id>[\w\.]+\.[\w\.\[\]-]+)\s+\.\.\.\s+(?P<st>ok|FAIL|ERROR|skipped)\b')
        for m in ut_re.finditer(log_text):
            add(m.group("id"), m.group("st"))

        # Go test style (if present): --- PASS/FAIL/SKIP: TestName
        go_re = re.compile(r'(?m)^---\s+(PASS|FAIL|SKIP):\s+([^\r\n]+)')
        for m in go_re.finditer(log_text):
            status = m.group(1)
            name = m.group(2)
            add(name, status)

        return results

    # 1) Try loading from file
    final_results = try_load_json_from_file()
    if final_results:
        return {k: map_status(v) for k, v in final_results.items()}

    # 2) Try parsing full JSON from provided log text
    final_results = try_load_json_from_log_text(log)
    if final_results:
        return {k: map_status(v) for k, v in final_results.items()}

    # 3) Object-aware scan of the text to pair nodeid and outcome in the same JSON object
    final_results = object_aware_scan(log)
    if final_results:
        return {k: map_status(v) for k, v in final_results.items()}

    # 4) Fallback to textual patterns
    final_results = parse_textual(log)
    if final_results:
        return {k: map_status(v) for k, v in final_results.items()}

    # If everything fails, return empty dict
    return {}

