def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def normalize_status(status: str) -> str:
        status = (status or "").strip().lower()
        if status in ("passed", "pass", "ok", "success"):
            return "pass"
        if status in ("skipped", "pending", "todo", "skip"):
            return "skip"
        return "fail"

    def normalize_name(name: str) -> str:
        name = name.replace("\r", "").replace("\n", "")
        name = re.sub(r"\s+", " ", name).strip()
        return name

    def extract_json_objects(text: str) -> list[str]:
        objs = []
        in_string = False
        escape = False
        depth = 0
        start = None
        for i, ch in enumerate(text):
            if in_string:
                if escape:
                    escape = False
                elif ch == "\\":
                    escape = True
                elif ch == '"':
                    in_string = False
                continue
            else:
                if ch == '"':
                    in_string = True
                    continue
                if ch == "{":
                    if depth == 0:
                        start = i
                    depth += 1
                elif ch == "}":
                    if depth > 0:
                        depth -= 1
                        if depth == 0 and start is not None:
                            objs.append(text[start : i + 1])
                            start = None
        return objs

    def sanitize_json_text(text: str) -> str:
        # Remove line-wrap newlines inside strings and de-duplicate wrap artifacts.
        out = []
        in_string = False
        escape = False
        i = 0
        while i < len(text):
            ch = text[i]
            if not in_string:
                if ch in "\r\n":
                    i += 1
                    continue
                if ch == '"':
                    in_string = True
                out.append(ch)
                i += 1
                continue

            # in_string
            if escape:
                out.append(ch)
                escape = False
                i += 1
                continue
            if ch == "\\":
                out.append(ch)
                escape = True
                i += 1
                continue
            if ch in "\r\n":
                # skip newlines inserted by wrapping
                j = i
                while j < len(text) and text[j] in "\r\n":
                    j += 1
                # If next character duplicates the last appended character, skip it once
                if j < len(text) and out:
                    next_char = text[j]
                    if out[-1] == next_char and out[-1].isalpha():
                        i = j + 1
                        continue
                i = j
                continue
            if ch == '"':
                in_string = False
            out.append(ch)
            i += 1
        return "".join(out)

    def parse_from_data(data):
        if not isinstance(data, dict):
            return
        test_results = data.get("testResults") or data.get("testresults") or []
        for suite in test_results:
            assertions = suite.get("assertionResults") or suite.get("assertionresults") or []
            for test in assertions:
                name = test.get("fullName") or test.get("fullname")
                if not name:
                    ancestor = test.get("ancestorTitles") or test.get("ancestortitles") or []
                    title = test.get("title") or ""
                    if ancestor:
                        name = " ".join([*ancestor, title]).strip()
                    else:
                        name = title.strip()
                if not name:
                    continue
                status = test.get("status") or ""
                results[normalize_name(name)] = normalize_status(status)

    def parse_with_regex(text: str):
        # Make a sanitized version to reduce line-wrap issues
        fixed = sanitize_json_text(text)
        pattern = re.compile(
            r'"fullName"\s*:\s*"(?P<name>(?:\\.|[^"\\])*)".*?"status"\s*:\s*"(?P<status>[A-Za-z]+)"',
            re.S,
        )
        for m in pattern.finditer(fixed):
            name = m.group("name")
            status = m.group("status")
            try:
                name = json.loads(f'"{name}"')
            except Exception:
                pass
            if not name:
                continue
            results[normalize_name(name)] = normalize_status(status)

    # Extract JSON objects from the log; if none, fallback to regex
    objs = extract_json_objects(log)
    if not objs:
        parse_with_regex(log)
        return results

    for obj in objs:
        sanitized = sanitize_json_text(obj)
        try:
            data = json.loads(sanitized)
        except Exception:
            parse_with_regex(obj)
            continue
        parse_from_data(data)

    return results

