def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def map_status(raw: str, has_failures: bool = False) -> str:
        status = (raw or "").lower()
        if status in ("passed", "pass", "success"):
            return "pass"
        if status in ("failed", "fail", "error"):
            return "fail"
        if status in ("skipped", "pending", "todo", "disabled", "skip"):
            return "skip"
        return "fail" if has_failures else "skip"

    def unescape_json_string(value: str) -> str:
        try:
            return json.loads(f'"{value}"')
        except Exception:
            return value.replace('\\"', '"').replace("\\n", "\n")

    def strip_prompts(text: str) -> list[str]:
        lines = []
        for line in text.splitlines():
            stripped = line.strip()
            if stripped.startswith("PS ") or stripped.startswith("PS>"):
                continue
            lines.append(line.rstrip("\r"))
        return lines

    def unwrap_lines(lines: list[str]) -> str:
        if not lines:
            return ""
        combined = lines[0]
        for line in lines[1:]:
            if not line:
                continue
            if combined:
                # If the line break duplicated a character, drop the leading duplicate
                if combined[-1] == line[0] and combined[-1].isalnum():
                    combined += line[1:]
                else:
                    combined += line
            else:
                combined = line
        return combined

    lines = strip_prompts(log)
    cleaned = unwrap_lines(lines)

    # Try JSON parse using raw_decode from any '{'
    data = None
    decoder = json.JSONDecoder()
    for idx, ch in enumerate(cleaned):
        if ch != "{":
            continue
        try:
            obj, _ = decoder.raw_decode(cleaned[idx:])
        except Exception:
            continue
        if isinstance(obj, dict) and ("testResults" in obj or "test_results" in obj):
            data = obj
            break

    if isinstance(data, dict):
        test_results = data.get("testResults") or data.get("test_results") or []
        for suite in test_results:
            suite_name = suite.get("name") or suite.get("testFilePath") or suite.get("file") or ""
            assertion_results = suite.get("assertionResults") or suite.get("assertion_results") or []
            if assertion_results:
                for case in assertion_results:
                    full_name = case.get("fullName") or case.get("full_name")
                    if not full_name:
                        title = case.get("title") or case.get("name") or ""
                        ancestors = case.get("ancestorTitles") or case.get("ancestor_titles") or []
                        if ancestors or title:
                            full_name = " ".join([*ancestors, title]).strip()
                        else:
                            continue
                    status = case.get("status") or ""
                    outcome = map_status(status, bool(case.get("failureMessages") or case.get("failure_messages")))
                    test_name = f"{suite_name}::{full_name}" if suite_name else full_name
                    results[test_name] = outcome
            else:
                status = suite.get("status") or ""
                if map_status(status) == "fail":
                    suite_key = suite_name or suite.get("name") or "unknown suite"
                    results[f"{suite_key}::(suite)"] = "fail"
        if results:
            return results

    # Fallback: regex parse JSON-like content
    block_re = re.compile(
        r'"assertionResults":\[(.*?)\]\s*,\s*"startTime".*?"name":"(.*?)"',
        re.DOTALL,
    )
    case_re = re.compile(
        r'"fullName":"(.*?)".*?"status":"(passed|failed|skipped|pending|todo|disabled)"',
        re.DOTALL,
    )
    for block in block_re.finditer(cleaned):
        assertion_block, suite_name = block.groups()
        suite_name = unescape_json_string(suite_name)
        for case_match in case_re.finditer(assertion_block):
            full_name, status = case_match.groups()
            full_name = unescape_json_string(full_name)
            outcome = map_status(status)
            test_name = f"{suite_name}::{full_name}" if suite_name else full_name
            results[test_name] = outcome
    if results:
        return results

    # Fallback for common test output formats
    pytest_re = re.compile(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)", re.MULTILINE)
    for test_name, status in pytest_re.findall(log):
        results[test_name] = map_status(status.lower())

    go_re = re.compile(r"^--- (PASS|FAIL|SKIP): (\S+)", re.MULTILINE)
    for status, test_name in go_re.findall(log):
        results[test_name] = map_status(status.lower())

    jest_re = re.compile(r"^\s*(✓|✕|○)\s+(.*)$", re.MULTILINE)
    for symbol, name in jest_re.findall(log):
        if symbol == "✓":
            results[name.strip()] = "pass"
        elif symbol == "✕":
            results[name.strip()] = "fail"
        else:
            results[name.strip()] = "skip"

    junit_case_re = re.compile(r"<testcase[^>]*?name=\"([^\"]+)\"[^>]*?>", re.MULTILINE)
    junit_fail_re = re.compile(r"<testcase[^>]*?name=\"([^\"]+)\"[^>]*?>(?:.|\n)*?<failure", re.MULTILINE)
    junit_error_re = re.compile(r"<testcase[^>]*?name=\"([^\"]+)\"[^>]*?>(?:.|\n)*?<error", re.MULTILINE)
    junit_skip_re = re.compile(r"<testcase[^>]*?name=\"([^\"]+)\"[^>]*?>(?:.|\n)*?<skipped", re.MULTILINE)

    if "<testcase" in log:
        for name in junit_case_re.findall(log):
            results[name] = "pass"
        for name in junit_fail_re.findall(log):
            results[name] = "fail"
        for name in junit_error_re.findall(log):
            results[name] = "fail"
        for name in junit_skip_re.findall(log):
            results[name] = "skip"

    return results

