index 0000000000..f919ce8731
--- /dev/null
+++ b/src/tests/web-bridge-package-root.test.ts
@@ -0,0 +1,70 @@
+/**
+ * Regression tests for the default package root fallback in bridge-service.
+ *
+ * Issue: gsd-build/gsd-2#1881
+ * The standalone Next.js bundle bakes import.meta.url at build time with the
+ * CI runner's absolute path.  On Windows, fileURLToPath() rejects the Unix
+ * file:// URL at module load time, 500-ing all API routes.
+ *
+ * The fix makes the fallback lazy and catch-guarded so the module loads safely
+ * on any OS regardless of what import.meta.url resolved to at build time.
+ */
+
+import test from "node:test";
+import assert from "node:assert/strict";
+import { resolve } from "node:path";
+
+const bridge = await import("../web/bridge-service.ts");
+
+test("resolveBridgeRuntimeConfig uses GSD_WEB_PACKAGE_ROOT when set", () => {
+  const env = {
+    GSD_WEB_PACKAGE_ROOT: "/custom/package/root",
+    GSD_WEB_PROJECT_CWD: "/some/project",
+  } as unknown as NodeJS.ProcessEnv;
+
+  const config = bridge.resolveBridgeRuntimeConfig(env);
+  assert.equal(config.packageRoot, "/custom/package/root");
+});
+
+test("resolveBridgeRuntimeConfig falls back to lazy default when GSD_WEB_PACKAGE_ROOT is absent", () => {
+  // Reset the memoized value so we exercise the lazy computation path.
+  bridge.resetDefaultPackageRootForTests();
+
+  const env = {
+    GSD_WEB_PROJECT_CWD: "/some/project",
+  } as unknown as NodeJS.ProcessEnv;
+
+  // Should not throw — the lazy getter catches cross-platform failures.
+  const config = bridge.resolveBridgeRuntimeConfig(env);
+  assert.equal(typeof config.packageRoot, "string");
+  assert.ok(config.packageRoot.length > 0, "packageRoot must be a non-empty string");
+});
+
+test("lazy default package root is an absolute path", () => {
+  bridge.resetDefaultPackageRootForTests();
+
+  const env = {
+    GSD_WEB_PROJECT_CWD: "/some/project",
+  } as unknown as NodeJS.ProcessEnv;
+
+  const config = bridge.resolveBridgeRuntimeConfig(env);
+  // resolve() returns the same path if already absolute.
+  assert.equal(config.packageRoot, resolve(config.packageRoot));
+});
+
+test("lazy default package root is memoized across calls", () => {
+  bridge.resetDefaultPackageRootForTests();
+
+  const env = {} as unknown as NodeJS.ProcessEnv;
+
+  const first = bridge.resolveBridgeRuntimeConfig(env).packageRoot;
+  const second = bridge.resolveBridgeRuntimeConfig(env).packageRoot;
+  assert.equal(first, second, "memoized value should be stable across calls");
+});
+
+test("module loads without throwing (regression: eager fileURLToPath crash)", () => {
+  // The fact that we can import bridge-service at the top of this file without
+  // an unhandled exception is itself the primary regression gate.  This test
+  // makes that contract explicit.
+  assert.ok(typeof bridge.resolveBridgeRuntimeConfig === "function");
+});

log_parser:
def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}

    def strip_prompt(line: str) -> str:
        line = line.rstrip("\r")
        if line.lstrip().startswith("PS>"):
            # remove PowerShell prompt
            idx = line.find("PS>")
            line = line[idx + 3 :]
            return line.lstrip()
        return line

    def is_tap_control(line: str) -> bool:
        stripped = line.strip()
        if not stripped:
            return True
        if stripped.startswith("TAP version"):
            return True
        if re.match(r"^\d+\.\.\d+$", stripped):
            return True
        if stripped.startswith("#"):
            return True
        if re.match(r"^(ok|not ok)\b", stripped):
            return True
        # YAML diagnostics block indicators
        if stripped in ("---", "..."):
            return True
        if re.match(r"^[A-Za-z0-9_-]+:\s", stripped) and line.startswith("  "):
            return True
        return False

    def is_continuation(line: str) -> bool:
        stripped = line.strip()
        if not stripped:
            return False
        if is_tap_control(line):
            return False
        # Indented YAML block lines are not continuations
        if line.startswith("  "):
            return False
        return True

    def join_wrapped(prev: str, nxt: str) -> str:
        prev_raw = prev
        # Use single space if either side suggests a word break
        if prev_raw.endswith(" ") or nxt.startswith(" "):
            return prev_raw.rstrip() + " " + nxt.lstrip()
        return prev_raw + nxt.lstrip()

    # Preprocess lines: strip prompts
    raw_lines = [strip_prompt(line) for line in log.splitlines()]

    # Reconstruct wrapped TAP ok/not ok lines
    reconstructed: list[str] = []
    pending: str | None = None
    pending_is_tap = False

    for line in raw_lines:
        if pending_is_tap and pending is not None:
            if is_continuation(line):
                pending = join_wrapped(pending, line)
                continue
            reconstructed.append(pending)
            pending = None
            pending_is_tap = False

        if re.match(r"^\s*(ok|not ok)\b", line):
            pending = line.strip()
            pending_is_tap = True
        else:
            reconstructed.append(line)

    if pending_is_tap and pending is not None:
        reconstructed.append(pending)

    # Parse TAP results
    for line in reconstructed:
        stripped = line.strip()
        if not stripped:
            continue

        # TAP ok/not ok
        tap_match = re.match(r"^(ok|not ok)\b(?:\s+(\d+))?(?:\s*-\s*)?(.*)$", stripped)
        if tap_match:
            status_word, num, name = tap_match.groups()
            name = (name or "").strip()
            # Handle directives (# SKIP / # TODO)
            directive_match = re.search(r"\s+#\s*(SKIP|TODO)\b.*$", name, re.IGNORECASE)
            if directive_match:
                name = name[: directive_match.start()].rstrip()
                status = "skip"
            else:
                status = "pass" if status_word == "ok" else "fail"

            if not name:
                name = f"test {num or ''}".strip()
            if name:
                results[name] = status
            continue

        # Go test style
        go_match = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(.+)$", stripped)
        if go_match:
            state, name = go_match.groups()
            state = state.upper()
            status = "pass" if state == "PASS" else "skip" if state == "SKIP" else "fail"
            results[name.strip()] = status
            continue

        # Pytest style
        pytest_match = re.match(
            r"^(.+?)::(.+?)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)$",
            stripped,
        )
        if pytest_match:
            file_part, test_part, state = pytest_match.groups()
            name = f"{file_part}::{test_part}"
            state = state.upper()
            if state in ("PASSED", "XPASS"):
                status = "pass"
            elif state in ("SKIPPED", "XFAIL"):
                status = "skip"
            else:
                status = "fail"
            results[name] = status
            continue

        # unittest style
        unit_match = re.match(r"^([A-Za-z0-9_.]+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)$", stripped)
        if unit_match:
            name, state = unit_match.groups()
            state_lower = state.lower()
            if state_lower == "ok":
                status = "pass"
            elif state_lower == "skipped":
                status = "skip"
            else:
                status = "fail"
            results[name] = status
            continue

        # Jest style
        jest_pass = re.match(r"^[✓√]\s+(.*)$", stripped)
        if jest_pass:
            results[jest_pass.group(1).strip()] = "pass"
            continue
        jest_fail = re.match(r"^[✕xX]\s+(.*)$", stripped)
        if jest_fail:
            results[jest_fail.group(1).strip()] = "fail"
            continue

    return results

