def parser(log: str) -> dict[str, str]:
    import re
    import html
    import xml.etree.ElementTree as ET

    _rank = {"pass": 0, "skip": 1, "fail": 2}

    def _set_result(results: dict[str, str], name: str, status: str) -> None:
        if not name:
            return
        prev = results.get(name)
        if prev is None or _rank[status] > _rank[prev]:
            results[name] = status

    def _dedupe_name(results: dict[str, str], base: str) -> str:
        if base not in results:
            return base
        i = 2
        while f"{base} [{i}]" in results:
            i += 1
        return f"{base} [{i}]"

    def _normalize_wrapped_xml_all(s: str) -> str:
        # Remove newlines inside tags (<...>) to undo PowerShell wrapping.
        s = s.replace("\r\n", "\n").replace("\r", "\n")
        out = []
        in_tag = False
        for ch in s:
            if ch == "<":
                in_tag = True
                out.append(ch)
            elif ch == ">":
                in_tag = False
                out.append(ch)
            elif in_tag and ch == "\n":
                continue
            else:
                out.append(ch)
        return "".join(out)

    def _localname(tag: str) -> str:
        return tag.rsplit("}", 1)[-1] if "}" in tag else tag

    def _iter_testcases(root: ET.Element):
        for el in root.iter():
            if isinstance(el.tag, str) and _localname(el.tag).lower() == "testcase":
                yield el

    def _status_from_tc_elem(tc: ET.Element) -> str:
        status = "pass"
        for el in tc.iter():
            if el is tc or not isinstance(el.tag, str):
                continue
            t = _localname(el.tag).lower()
            if t in ("failure", "error"):
                return "fail"
            if t in ("skipped", "skip"):
                status = "skip"
        return status

    def _clean_name(s: str) -> str:
        s = html.unescape(s or "")
        s = re.sub(r"\s+", " ", s).strip()
        return s

    def _name_from_tc_attrib(attrib: dict) -> str:
        classname = _clean_name(attrib.get("classname", ""))
        name = _clean_name(attrib.get("name", ""))
        if classname and name:
            return f"{classname}::{name}"
        return name or classname

    def _parse_xml_doc(results: dict[str, str], xml_text: str) -> None:
        xml_text = xml_text.strip()
        if not xml_text:
            return
        try:
            root = ET.fromstring(xml_text)
        except Exception:
            return
        for tc in _iter_testcases(root):
            base = _name_from_tc_attrib(tc.attrib)
            if not base:
                continue
            status = _status_from_tc_elem(tc)
            name = base if base not in results else _dedupe_name(results, base)
            _set_result(results, name, status)

    results: dict[str, str] = {}
    norm = _normalize_wrapped_xml_all(log)

    # Try full XML extraction first.
    xml_blocks = []
    for m in re.finditer(r"<testsuites\b[^>]*>.*?</testsuites\s*>", norm, re.I | re.S):
        xml_blocks.append(m.group(0))
    for m in re.finditer(r"<testsuite\b[^>]*>.*?</testsuite\s*>", norm, re.I | re.S):
        xml_blocks.append(m.group(0))

    for xb in xml_blocks:
        _parse_xml_doc(results, xb)

    # If XML parse yields too few results, fall back to tolerant testcase scanning
    # that doesn't require balanced suite roots (handles truncated logs).
    if len(results) < 1000:
        # Robust attribute capture: name can include hyphens/colons; support ' or "
        attr_re = re.compile(r'([^\s=/>]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')')

        def parse_attrs(tag_text: str) -> dict[str, str]:
            attrs = {}
            for am in attr_re.finditer(tag_text):
                key = am.group(1)
                val = am.group(2) if am.group(2) is not None else am.group(3)
                attrs[key] = val
            return attrs

        s = norm
        lower = s.lower()
        starts = [m.start() for m in re.finditer(r"<testcase\b", lower)]
        for idx, st in enumerate(starts):
            gt = s.find(">", st)
            if gt == -1:
                continue
            open_tag = s[st : gt + 1]
            self_closing = open_tag.rstrip().endswith("/>")
            attrs = parse_attrs(open_tag)
            base = _name_from_tc_attrib(attrs)
            if not base:
                continue

            # Determine inner range for status detection
            inner_start = gt + 1
            inner_end = inner_start
            if self_closing:
                inner = ""
            else:
                close = lower.find("</testcase", inner_start)
                if close != -1:
                    inner_end = close
                else:
                    # truncated: end at next testcase start or end of string
                    nxt = starts[idx + 1] if idx + 1 < len(starts) else len(s)
                    inner_end = nxt
                inner = lower[inner_start:inner_end]

            status = "pass"
            if "<failure" in inner or "<error" in inner:
                status = "fail"
            elif "<skipped" in inner or "<skip" in inner:
                status = "skip"

            name = base
            if name in results:
                # preserve worst; if same status and already present, keep existing
                if _rank[status] > _rank[results[name]]:
                    results[name] = status
                elif results[name] == status:
                    continue
                else:
                    name = _dedupe_name(results, name)
                    results[name] = status
            else:
                results[name] = status

    # Final fallback for non-XML frameworks if still empty
    if not results:
        text = norm.replace("\r\n", "\n").replace("\r", "\n")
        for m in re.finditer(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", text, re.M):
            name, st = m.group(1), m.group(2)
            _set_result(results, name, "pass" if st == "PASSED" else "skip" if st == "SKIPPED" else "fail")
        for m in re.finditer(r"^--- (PASS|FAIL|SKIP):\s*(\S+)", text, re.M):
            st, name = m.group(1), m.group(2)
            _set_result(results, name, "pass" if st == "PASS" else "skip" if st == "SKIP" else "fail")

    return results

