def parser(log: str) -> dict[str, str]:
    """
    Parse Vitest/Jest JSON report printed via PowerShell Get-Content -Raw.

    Strategy:
    1) Aggressively isolate the JSON report object from surrounding noise.
    2) Remove CR/LF inserted by PowerShell wrapping.
    3) json.loads and validate schema/counters.
    4) Extract every assertionResult with correct status mapping.
    5) Fallback (only if JSON cannot be parsed): conservative regex that will not
       fabricate failures by mis-pairing fields.
    """
    import json
    import re

    def norm_status(s: str) -> str:
        s = (s or "").strip().lower()
        if s in ("passed", "pass", "ok", "success"):
            return "pass"
        if s in ("skipped", "skip", "pending", "todo", "disabled"):
            return "skip"
        return "fail"

    def unique(base: str, used: set[str]) -> str:
        if base not in used:
            used.add(base)
            return base
        i = 2
        while f"{base} [{i}]" in used:
            i += 1
        name = f"{base} [{i}]"
        used.add(name)
        return name

    def isolate_json(text: str) -> str | None:
        if not text:
            return None
        t = text.replace("\ufeff", "").replace("\x00", "")

        # Start at a strong signature if possible
        sigs = [
            '{"numTotalTestSuites"',
            '{"numTotalTests"',
            '{"success"',
            '{"testResults"',
        ]
        start = -1
        for sig in sigs:
            pos = t.find(sig)
            if pos != -1 and (start == -1 or pos < start):
                start = pos

        if start == -1:
            # fallback to first '{'
            start = t.find("{")
        if start == -1:
            return None

        end = t.rfind("}")
        if end == -1 or end <= start:
            return None

        cand = t[start : end + 1]

        # Undo PowerShell wrapping
        cand = cand.replace("\r", "").replace("\n", "")
        return cand.strip()

    def validate_report(obj: object) -> bool:
        if not isinstance(obj, dict):
            return False
        tr = obj.get("testResults")
        if not isinstance(tr, list) or len(tr) == 0:
            return False
        # Basic keys usually exist
        if "numTotalTests" not in obj and "success" not in obj:
            return False
        return True

    def count_assertions(obj: dict) -> int:
        total = 0
        tr = obj.get("testResults", [])
        if not isinstance(tr, list):
            return 0
        for suite in tr:
            if not isinstance(suite, dict):
                continue
            ars = suite.get("assertionResults", [])
            if isinstance(ars, list):
                total += len(ars)
        return total

    def parse_report(obj: dict) -> dict[str, str]:
        results: dict[str, str] = {}
        used: set[str] = set()

        suites = obj.get("testResults", [])
        for suite_i, suite in enumerate(suites):
            if not isinstance(suite, dict):
                continue
            suite_name = str(suite.get("name") or "").strip()

            assertions = suite.get("assertionResults", [])
            if not isinstance(assertions, list):
                assertions = []

            for case_i, case in enumerate(assertions):
                if not isinstance(case, dict):
                    continue
                st = norm_status(str(case.get("status") or ""))

                title = str(case.get("title") or "").strip()
                full = str(case.get("fullName") or "").strip()
                anc = case.get("ancestorTitles")
                anc_list = []
                if isinstance(anc, list):
                    anc_list = [str(a).strip() for a in anc if str(a).strip()]

                if anc_list or title:
                    test_id = " > ".join([*anc_list, title]).strip(" >")
                else:
                    test_id = full or f"test[{suite_i}:{case_i}]"

                name = f"{suite_name}::{test_id}" if suite_name else test_id
                results[unique(name, used)] = st

        return results

    # ---- main: JSON path ----
    cand = isolate_json(log or "")
    if cand:
        try:
            obj = json.loads(cand)
            if validate_report(obj):
                # Validate counters if available; if mismatch is extreme, consider invalid parse.
                expected = obj.get("numTotalTests")
                found = count_assertions(obj)
                if isinstance(expected, int):
                    # Accept if close; Vitest sometimes counts differently with retries,
                    # but should be in the same order of magnitude.
                    if expected > 0 and (found == 0 or abs(found - expected) > max(50, expected // 2)):
                        raise ValueError("Parsed JSON but assertion count mismatch; likely wrong substring.")
                res = parse_report(obj)

                # Sanity: if root says no failures, don't allow any fail statuses.
                if isinstance(obj.get("numFailedTests"), int) and obj.get("numFailedTests") == 0:
                    if any(v == "fail" for v in res.values()):
                        raise ValueError("Root reports 0 failed tests but parsed failures; likely wrong parse.")

                return res
        except Exception:
            pass

    # ---- conservative fallback (no fabricated fails) ----
    # If JSON can't be parsed, do best-effort extraction of *explicit* statuses.
    # Default to "pass" unless status explicitly indicates skip/fail.
    results: dict[str, str] = {}
    used: set[str] = set()
    s = (log or "").replace("\ufeff", "").replace("\x00", "").replace("\r", "").replace("\n", "")

    # Try to capture individual assertion-like objects and read status/name within same object.
    start_re = re.compile(r'\{(?=[^{}]*"status"\s*:\s*")')
    # optional suite names
    suite_iter = list(
        re.finditer(r'"name"\s*:\s*"((?:\\.|[^"\\])*)"\s*,\s*"assertionResults"\s*:\s*\[', s)
    )

    def unesc(val: str) -> str:
        try:
            return json.loads(f'"{val}"')
        except Exception:
            return val.replace('\\"', '"').replace("\\\\", "\\")

    regions = []
    if suite_iter:
        for i, m in enumerate(suite_iter):
            st = m.end()
            en = suite_iter[i + 1].start() if i + 1 < len(suite_iter) else len(s)
            regions.append((unesc(m.group(1)), s[st:en]))
    else:
        regions.append(("", s))

    for suite_name, region in regions:
        for m in start_re.finditer(region):
            i = m.start()
            depth = 0
            j = i
            while j < len(region):
                ch = region[j]
                if ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        j += 1
                        break
                j += 1
            if depth != 0:
                continue
            obj_txt = region[i:j]

            ms = re.search(r'"status"\s*:\s*"((?:\\.|[^"\\])*)"', obj_txt)
            if not ms:
                continue
            status_raw = unesc(ms.group(1))
            status = status_raw.strip().lower()

            # Extract name
            mf = re.search(r'"fullName"\s*:\s*"((?:\\.|[^"\\])*)"', obj_txt)
            mt = re.search(r'"title"\s*:\s*"((?:\\.|[^"\\])*)"', obj_txt)
            test_id = unesc((mf.group(1) if mf else "") or (mt.group(1) if mt else "")).strip()
            if not test_id:
                continue

            # Conservative status mapping in fallback:
            if status in ("skipped", "skip", "pending", "todo", "disabled"):
                st = "skip"
            elif status in ("failed", "fail", "error"):
                st = "fail"
            else:
                st = "pass"

            name = f"{suite_name}::{test_id}" if suite_name else test_id
            results[unique(name, used)] = st

    return results

