def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}

    def map_status(st: str) -> str:
        st = st.lower()
        if st in ("passed", "pass", "ok", "success", "✓"):
            return "pass"
        if st in ("skipped", "skip", "pending", "ignored", "○"):
            return "skip"
        return "fail"

    def clean_line(s: str) -> str:
        s = s.replace("\ufeff", "")
        s = re.sub(r"^\s*PS [^>]*>\s*", "", s)
        s = re.sub(r"^\s*PS>\s*", "", s)
        return s.rstrip("\r")

    def normalize_name(raw: str) -> str:
        raw = raw.replace("\ufeff", "").strip()

        # Remove line-wrap artifacts where a path got split as "/r\nroot" -> "/root"
        raw = re.sub(r"/([a-zA-Z])\n([A-Za-z])", r"/\2", raw)

        # Fix word splits across wrapped newlines: "chil\nd" -> "child"
        raw = re.sub(r"([A-Za-z0-9])\n([a-z0-9])", r"\1\2", raw)

        # Replace remaining newlines with single spaces
        raw = re.sub(r"\n+", " ", raw)
        raw = re.sub(r"\s+", " ", raw).strip()

        # Strip trailing punctuation
        raw = re.sub(r"[\-–—:]+$", "", raw).strip()
        return raw

    # --------- JUnit XML (if present) ----------
    if "<testsuite" in log and "<testcase" in log:
        try:
            import xml.etree.ElementTree as ET

            xml_start = re.search(r"(?is)<testsuite\b", log)
            if xml_start:
                root = ET.fromstring(log[xml_start.start() :])
                for tc in root.iter():
                    if tc.tag.lower().endswith("testcase"):
                        name = tc.attrib.get("name", "").strip()
                        classname = tc.attrib.get("classname", "").strip()
                        full = f"{classname}.{name}".strip(".") if classname else name
                        status = "pass"
                        for ch in list(tc):
                            tag = ch.tag.lower()
                            if tag.endswith("skipped"):
                                status = "skip"
                                break
                            if tag.endswith("failure") or tag.endswith("error"):
                                status = "fail"
                                break
                        if full:
                            results[full] = status
                if results:
                    return results
        except Exception:
            pass

    # --------- Physical lines (strip prompts/commands) ----------
    phys_lines: list[str] = []
    for ln in log.splitlines():
        if not ln or not ln.strip():
            continue
        if re.match(r"^\s*PS(?: [^>]*)?>\s*$", ln):
            continue
        if re.match(r"^\s*PS(?: [^>]*)?>.*\b(Get-Content|cd)\b", ln):
            continue
        phys_lines.append(clean_line(ln))

    # --------- Assemble logical test records ----------
    # Primary: status is aligned with >=2 spaces or a tab before it (as in the file)
    end_status_re = re.compile(r"(?i)\s{2,}(passed|failed|skipped)\s*$")
    # Wrapped status: previous line ended with 'p' and next line is 'passed'
    status_only_re = re.compile(r"(?i)^(passed|failed|skipped)\s*$")

    cur = ""
    for ln in phys_lines:
        s = ln.rstrip()
        if not s.strip():
            continue

        # If this line is only status, close record if we have a buffer
        mo = status_only_re.match(s.strip())
        if mo and cur:
            name = cur
            status = mo.group(1)
            cur = ""
            nm = normalize_name(name)
            if nm:
                results[nm] = map_status(status)
            continue

        # Append with newline to preserve wrap positions
        if cur:
            cur += "\n" + s
        else:
            cur = s

        m = end_status_re.search(cur)
        if m:
            status = m.group(1)
            name = cur[: m.start()].rstrip()

            # Fix specific artifact: trailing standalone letter before status due to wrap ("... p\npassed")
            name = re.sub(r"\b[a-zA-Z]\s*$", lambda mm: "" if len(mm.group(0).strip()) == 1 else mm.group(0), name)

            cur = ""
            nm = normalize_name(name)
            if nm:
                results[nm] = map_status(status)

    # Truncated tail without status is ignored

    # --------- Fallback single-line formats ----------
    for ln in phys_lines:
        s = ln.strip()
        m = re.match(r"^(.*?)(?:\s+)(PASSED|FAILED|SKIPPED|ERROR)\s*$", s, flags=re.I)
        if m:
            results.setdefault(normalize_name(m.group(1)), map_status(m.group(2)))
            continue
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(.+?)(?:\s+\(\d|\s*$)", s, flags=re.I)
        if m:
            results.setdefault(normalize_name(m.group(2)), map_status(m.group(1)))
            continue
        m = re.match(r"^\s*([✓✕○])\s+(.*?)\s*$", s)
        if m:
            results.setdefault(normalize_name(m.group(2)), map_status(m.group(1)))

    return results

