def parser(log: str) -> dict[str, str]:
    import re

    results: dict[str, str] = {}

    def norm_status(s: str) -> str:
        s = s.strip().lower()
        if s in ("pass", "passed", "ok", "success"):
            return "pass"
        if s in ("skip", "skipped", "ignored"):
            return "skip"
        return "fail"

    # A "plausible" .NET fully qualified test name:
    # Namespace.Class.Method(...) possibly with parameters, no spaces.
    fq_test_re = re.compile(r"^[A-Za-z_][\w`]*(?:\.[A-Za-z_][\w`]*)+\.[A-Za-z_][\w`]+(?:\(.+\))?$")

    def plausible_name(name: str) -> bool:
        name = name.strip()
        if not name or " " in name:
            return False
        if "\\testbed\\" in name.lower() or ":\\" in name:
            return False
        if name.startswith("[xUnit.net"):
            return False
        if name.startswith("----") or name.startswith("at "):
            return False
        return bool(fq_test_re.match(name))

    def set_result(name: str, status: str) -> None:
        name = name.strip()
        if plausible_name(name):
            results[name] = status

    # xUnit result line, allow optional prefix "dotnet.exe : "
    xu_line_re = re.compile(
        r"^(?:.*?:\s*)?\[xUnit\.net[^\]]*\]\s+(?P<name>\S+)\s+\[(?P<st>PASS|FAIL|SKIP)\]\s*$",
        re.IGNORECASE,
    )

    # VSTest detailed lines
    vstest_line_re = re.compile(
        r"^\s*(?P<st>Passed|Failed|Skipped)\s+(?P<name>\S+)\s+\[\s*(?:<\s*)?\d+.*\]\s*$",
        re.IGNORECASE,
    )

    pytest_re = re.compile(r"^(?P<name>\S+::\S+)\s+(?P<st>PASSED|FAILED|SKIPPED|ERROR)\s*$", re.IGNORECASE)
    gotest_re = re.compile(r"^---\s+(?P<st>PASS|FAIL|SKIP):\s+(?P<name>\S+)\s*$", re.IGNORECASE)

    # Reconstruct wrapped lines:
    # Only join when current buffer looks like a result start AND next line is indented continuation.
    raw_lines = log.splitlines()
    logical_lines: list[str] = []
    buf = ""

    def buf_needs_more(b: str) -> bool:
        if not b:
            return False
        if "[xUnit.net" in b and not re.search(r"\[(?:PASS|FAIL|SKIP)\]\s*$", b, re.IGNORECASE):
            return True
        if re.match(r"^\s*(Passed|Failed|Skipped)\b", b, re.IGNORECASE) and not re.search(
            r"\[\s*(?:<\s*)?\d+.*\]\s*$", b
        ):
            return True
        return False

    for line in raw_lines:
        l = line.rstrip("\r\n")
        if not buf:
            buf = l
            continue

        if buf_needs_more(buf) and (len(l) - len(l.lstrip(" ")) >= 2):
            # continuation line: keep exact content but strip leading spaces
            cont = l.lstrip()
            joiner = "" if (buf and buf[-1].isalnum() and cont and cont[0].isalnum()) else " "
            buf = buf + joiner + cont
            continue

        logical_lines.append(buf)
        buf = l

    if buf:
        logical_lines.append(buf)

    # Parse
    for ll in logical_lines:
        s = ll.strip()
        if not s:
            continue

        m = xu_line_re.match(s)
        if m:
            set_result(m.group("name"), norm_status(m.group("st")))
            continue

        m = vstest_line_re.match(s)
        if m:
            set_result(m.group("name"), norm_status(m.group("st")))
            continue

        m = pytest_re.match(s)
        if m:
            # pytest nodeid isn't FQ .NET name; accept as-is
            results[m.group("name")] = norm_status(m.group("st"))
            continue

        m = gotest_re.match(s)
        if m:
            results[m.group("name")] = norm_status(m.group("st"))
            continue

    return results

