def parser(log: str) -> dict[str, str]:
    import html
    import re
    from typing import Dict, Tuple, Optional

    def extract_xmlish(s: str) -> str:
        i = s.find("<?xml")
        if i != -1:
            return s[i:]
        i = s.find("<TestRun")
        return s[i:] if i != -1 else s

    def normalize_tag_region_wrapping(s: str) -> str:
        """
        Remove console hard-wrap artifacts *inside tags only*:
        - remove CR/LF and following indentation while inside <...>
        This preserves text nodes while making tags contiguous.
        """
        out = []
        in_tag = False
        quote = None
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if not in_tag:
                if ch == "<":
                    in_tag = True
                out.append(ch)
                i += 1
                continue

            # inside tag
            if quote is None:
                if ch in ("'", '"'):
                    quote = ch
                    out.append(ch)
                    i += 1
                    continue
                if ch == ">":
                    in_tag = False
                    out.append(ch)
                    i += 1
                    continue
                if ch in "\r\n":
                    j = i
                    while j < n and s[j] in "\r\n":
                        j += 1
                    while j < n and s[j] == " ":
                        j += 1
                    i = j
                    continue
                out.append(ch)
                i += 1
            else:
                if ch == quote:
                    quote = None
                    out.append(ch)
                    i += 1
                    continue
                if ch in "\r\n":
                    j = i
                    while j < n and s[j] in "\r\n":
                        j += 1
                    while j < n and s[j] == " ":
                        j += 1
                    i = j
                    continue
                out.append(ch)
                i += 1
        return "".join(out)

    def status_from_outcome(outcome: str) -> Optional[str]:
        o = (outcome or "").strip().lower()
        if o == "passed":
            return "pass"
        if o in {"failed", "error", "timeout", "notexecuted", "aborted"}:
            return "fail"
        if o in {"skipped", "inconclusive"}:
            return "skip"
        return None

    def parse_attributes(tag_text: str) -> Dict[str, str]:
        """
        Parse attributes from a single tag string like:
          UnitTestResult a="1" b='2' c=3
        Returns dict of raw attribute names->values (unescaped).
        Robust to extra spaces; stops at end of tag_text.
        """
        attrs: Dict[str, str] = {}
        i = 0
        n = len(tag_text)

        def skip_ws(k: int) -> int:
            while k < n and tag_text[k].isspace():
                k += 1
            return k

        i = skip_ws(i)
        # skip tag name
        while i < n and not tag_text[i].isspace():
            i += 1

        while i < n:
            i = skip_ws(i)
            if i >= n:
                break
            # attribute name
            j = i
            while j < n and (tag_text[j].isalnum() or tag_text[j] in ":-_"):
                j += 1
            if j == i:
                break
            name = tag_text[i:j]
            i = skip_ws(j)
            if i >= n or tag_text[i] != "=":
                # attribute without value; skip token
                continue
            i = skip_ws(i + 1)
            if i >= n:
                break
            if tag_text[i] in ("'", '"'):
                q = tag_text[i]
                i += 1
                start = i
                while i < n and tag_text[i] != q:
                    i += 1
                val = tag_text[start:i]
                if i < n and tag_text[i] == q:
                    i += 1
            else:
                start = i
                while i < n and not tag_text[i].isspace():
                    i += 1
                val = tag_text[start:i]
            attrs[name] = html.unescape(val)
        return attrs

    def canonicalize_attr_name(name: str) -> str:
        # tolerate wrapping typos like executionnId/outcomee/ouutcome/testtName etc.
        n = name.lower()
        n = re.sub(r"[^a-z]", "", n)
        # collapse repeated letters introduced by wrap (very conservative)
        n = re.sub(r"(.)\1+", r"\1", n)
        return n

    xmlish = normalize_tag_region_wrapping(extract_xmlish(log))
    results: Dict[str, str] = {}

    # Scan for each UnitTestResult tag without bleeding into next element.
    start_pat = re.compile(r"<\s*UnitTestResult\b", re.IGNORECASE)
    for m in start_pat.finditer(xmlish):
        start = m.start()
        # find end of this tag '>' respecting quotes
        i = m.end()
        quote = None
        while i < len(xmlish):
            ch = xmlish[i]
            if quote is None:
                if ch in ("'", '"'):
                    quote = ch
                elif ch == ">":
                    break
            else:
                if ch == quote:
                    quote = None
            i += 1
        if i >= len(xmlish) or xmlish[i] != ">":
            continue
        tag = xmlish[start + 1 : i]  # without surrounding <>
        attrs = parse_attributes(tag)

        # Map attrs by canonicalized name
        canon = {canonicalize_attr_name(k): v for k, v in attrs.items()}

        name = canon.get("testname")
        outcome = canon.get("outcome")

        if not name or not outcome:
            continue
        st = status_from_outcome(outcome)
        if st is None:
            continue
        results[name] = st

    return results

