def parser(log: str) -> dict[str, str]:
    import re
    from html import unescape
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    prec = {"pass": 0, "skip": 1, "fail": 2}

    def merge(name: str, status: str):
        if not name:
            return
        if status not in prec:
            status = "fail"
        cur = results.get(name)
        if cur is None or prec[status] > prec[cur]:
            results[name] = status

    def norm_status(outcome: str) -> str:
        if not outcome:
            return "fail"
        o = outcome.strip().lower()
        if o in ("passed", "pass", "success", "succeeded", "ok"):
            return "pass"
        if o in ("skipped", "skip", "notexecuted", "not executed", "inconclusive", "ignored", "disabled"):
            return "skip"
        return "fail"

    def norm_text(s: str) -> str:
        if s is None:
            return ""
        s = unescape(s)
        s = s.replace("\r", "").replace("\n", "")
        return s.strip()

    # Remove illegal control chars but keep \r\n\t
    log = re.sub(r"[\x00-\x08\x0B\x0C\x0E-\x1F]", "", log)
    log = re.sub(r"(?m)^\s*PS>\s*", "", log)

    def remove_newlines_inside_quotes(text: str) -> str:
        out = []
        in_quote = None
        for ch in text:
            if in_quote is None:
                if ch in ("'", '"'):
                    in_quote = ch
                out.append(ch)
            else:
                if ch == in_quote:
                    in_quote = None
                    out.append(ch)
                elif ch in ("\r", "\n"):
                    # drop wrapping newlines
                    pass
                else:
                    out.append(ch)
        return "".join(out)

    def parse_trx(root) -> bool:
        # Map testId -> canonical test name from TestDefinitions (less likely to include wrapped params)
        id_to_name: dict[str, str] = {}

        for ut in root.findall(".//{*}TestDefinitions/{*}UnitTest"):
            tid = norm_text(ut.attrib.get("id", ""))
            # TRX UnitTest has name="..." and optional TestMethod with className/name
            nm = norm_text(ut.attrib.get("name", ""))
            tm = ut.find(".//{*}TestMethod")
            if tm is not None:
                cls = norm_text(tm.attrib.get("className", ""))
                mname = norm_text(tm.attrib.get("name", ""))
                if cls and mname:
                    # Prefer method-based canonical name; it's stable and unparameterized
                    nm2 = f"{cls}.{mname}"
                    nm = nm2 or nm
            if tid and nm:
                id_to_name[tid] = nm

        parsed_any = False
        # Results
        for r in root.findall(".//{*}Results/{*}UnitTestResult"):
            tid = norm_text(r.attrib.get("testId", ""))
            tname = norm_text(r.attrib.get("testName", ""))
            name = id_to_name.get(tid) or tname
            status = norm_status(r.attrib.get("outcome", ""))
            if name:
                merge(name, status)
                parsed_any = True

        # Some TRX variants
        for r in root.findall(".//{*}Results/{*}TestResult"):
            tid = norm_text(r.attrib.get("testId", ""))
            tname = norm_text(r.attrib.get("testName", ""))
            name = id_to_name.get(tid) or tname
            status = norm_status(r.attrib.get("outcome", ""))
            if name:
                merge(name, status)
                parsed_any = True

        return parsed_any

    def parse_junit(root) -> bool:
        parsed_any = False
        for tc in root.findall(".//testcase"):
            name = norm_text(tc.attrib.get("name", ""))
            classname = norm_text(tc.attrib.get("classname", ""))
            full = (classname + "." + name).strip(".") if classname else name
            if not full:
                continue
            status = "pass"
            if tc.find("skipped") is not None:
                status = "skip"
            elif tc.find("failure") is not None or tc.find("error") is not None:
                status = "fail"
            merge(full, status)
            parsed_any = True
        return parsed_any

    def parse_xml_block(block: str) -> bool:
        block = re.sub(r"^.*?(<\?xml)", r"\1", block, flags=re.S | re.I)
        block = remove_newlines_inside_quotes(block)

        # Try parse directly
        try:
            root = ET.fromstring(block)
        except Exception:
            # salvage TRX
            m = re.search(r"(<TestRun\b.*?</TestRun>)", block, flags=re.S | re.I)
            if m:
                try:
                    root = ET.fromstring(m.group(1))
                except Exception:
                    return False
            else:
                m = re.search(r"(<testsuites?\b.*?</testsuites?>)", block, flags=re.S | re.I)
                if not m:
                    return False
                try:
                    root = ET.fromstring(m.group(1))
                except Exception:
                    return False

        # Decide type by root/localname
        tag = root.tag.lower()
        if tag.endswith("testrun"):
            return parse_trx(root)
        return parse_junit(root)

    # Extract XML blocks
    xml_blocks: list[str] = []
    for m in re.finditer(r"(<\?xml[^>]*\?>.*?</TestRun>)", log, flags=re.S | re.I):
        xml_blocks.append(m.group(1))
    for m in re.finditer(r"(<\?xml[^>]*\?>.*?</testsuites?>)", log, flags=re.S | re.I):
        xml_blocks.append(m.group(1))
    if not xml_blocks:
        m = re.search(r"(<\?xml[^>]*\?>.*)$", log, flags=re.S | re.I)
        if m:
            xml_blocks.append(m.group(1))

    parsed_any_xml = False
    for xb in xml_blocks:
        if parse_xml_block(xb):
            parsed_any_xml = True

    # Text fallbacks
    if not results:
        for m in re.finditer(r"(?m)^\s*(.+?::\S+)\s+(PASSED|FAILED|SKIPPED|XFAILED|XPASSED|ERROR)\s*$", log):
            merge(norm_text(m.group(1)), norm_status(m.group(2)))

        for m in re.finditer(r"(?m)^\s*(\S+)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\s*$", log):
            merge(norm_text(f"{m.group(2)}.{m.group(1)}"), norm_status(m.group(3)))

        for m in re.finditer(r"(?m)^\s*---\s+(PASS|FAIL|SKIP):\s+(\S+)", log):
            merge(norm_text(m.group(2)), norm_status(m.group(1)))

    # Last resort regex if XML could not be parsed at all
    if not parsed_any_xml and not results:
        attrs_text = remove_newlines_inside_quotes(log)
        for m in re.finditer(r"<UnitTestResult\b(.*?)(?:/?>)", attrs_text, flags=re.S | re.I):
            attrs = m.group(1)
            nm = re.search(r'testName\s*=\s*(["\'])(.*?)\1', attrs, flags=re.S | re.I)
            om = re.search(r'outcome\s*=\s*(["\'])(.*?)\1', attrs, flags=re.S | re.I)
            if not nm or not om:
                continue
            merge(norm_text(nm.group(2)), norm_status(om.group(2)))

    return results

