def parser(log: str) -> dict[str, str]:
    import re
    import html
    import xml.etree.ElementTree as ET

    def normalize_status(outcome: str) -> str:
        o = (outcome or "").strip().lower()
        if o == "passed":
            return "pass"
        if o in ("notexecuted", "skipped", "skip"):
            return "skip"
        return "fail"

    def merge_status(prev: str | None, new: str) -> str:
        # Worst-of aggregation: fail > skip > pass
        if prev is None:
            return new
        order = {"pass": 0, "skip": 1, "fail": 2}
        return prev if order[prev] >= order[new] else new

    # 1) Remove obvious shell noise lines while keeping XML content.
    # Keep all other lines because some test names may include odd characters.
    lines = log.splitlines()
    filtered = []
    for ln in lines:
        if re.match(r"^\s*PS>\s*", ln):
            # drop PowerShell prompts
            continue
        filtered.append(ln)
    s = "\n".join(filtered)

    # 2) Drop leading BOM / mojibake BOM marker from `type` output.
    s = s.lstrip("\ufeff")
    # Common UTF-8 BOM rendered as characters in some consoles: "ï»¿" or "∩╗┐"
    s = re.sub(r"^(?:ï»¿|∩╗┐)+", "", s)

    # 3) Trim to XML-ish region if present.
    start = s.find("<?xml")
    if start == -1:
        start = s.find("<TestRun")
    if start != -1:
        s = s[start:]

    # 4) De-wrap console line breaks inside XML tags/attribute values.
    # The `type` output can hard-wrap long lines, inserting newlines inside tags.
    out = []
    in_tag = False
    in_quote = False
    quote_ch = ""
    for ch in s:
        if ch == "<" and not in_quote:
            in_tag = True
            out.append(ch)
            continue
        if ch == ">" and in_tag and not in_quote:
            in_tag = False
            out.append(ch)
            continue
        if in_tag:
            if ch in ("'", '"'):
                if not in_quote:
                    in_quote = True
                    quote_ch = ch
                elif quote_ch == ch:
                    in_quote = False
                    quote_ch = ""
            # Remove hard wraps within tags/attributes.
            if ch in "\r\n":
                continue
            out.append(ch)
        else:
            # Outside tags: normalize newlines to spaces (avoid word-joins in text nodes).
            if ch in "\r\n":
                out.append(" ")
            else:
                out.append(ch)
    xmlish = "".join(out)

    results: dict[str, str] = {}

    # 5) Try proper XML parsing first (TRX).
    try:
        # If the log is truncated, ElementTree will fail; we'll regex-fallback.
        root = ET.fromstring(xmlish)
        ns = ""
        if root.tag.startswith("{"):
            ns = root.tag.split("}")[0].strip("{")

        def q(tag: str) -> str:
            return f"{{{ns}}}{tag}" if ns else tag

        for utr in root.findall(".//" + q("UnitTestResult")):
            name = utr.attrib.get("testName", "") or ""
            outcome = utr.attrib.get("outcome", "") or ""
            if not name:
                continue
            name = html.unescape(name).strip()
            status = normalize_status(outcome)
            results[name] = merge_status(results.get(name), status)

        if results:
            return results
    except Exception:
        pass

    # 6) Regex fallback: find <UnitTestResult ... /> blocks even in partial XML.
    # We intentionally avoid altering internal whitespace so testName stays intact after de-wrap.
    tag_re = re.compile(r"<UnitTestResult\b.*?(?:/>)", re.IGNORECASE | re.DOTALL)
    attr_re = re.compile(r'([A-Za-z_][\w\.\-:]*)\s*=\s*"([^"]*)"', re.DOTALL)

    for m in tag_re.finditer(xmlish):
        tag = m.group(0)
        attrs = {k: v for k, v in attr_re.findall(tag)}
        name = html.unescape((attrs.get("testName") or "").strip())
        if not name:
            continue
        status = normalize_status(attrs.get("outcome", ""))
        results[name] = merge_status(results.get(name), status)

    return results
